}
.header-actions button:hover {
    background-color: #333;
}

/* Main content */
#maincontent {
    /* remove outline from tabindex="-1" */
    outline: none;
}

section {
    padding: var(--spacing-xl) var(--spacing-md);
    max-width: 1200px;
    margin: 0 auto;
}

section h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-lg);
    border-bottom: 1px solid #333;
    padding-bottom: var(--spacing-sm);
}

/* Hero Section */
