.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    font-weight: bold;
    text-decoration: none;
    border-radius: 4px;
    text-align: center;
}

.btn-primary {
    background-color: var(--accent-color);
    color: #121212;
}

.btn-primary:hover {
    background-color: var(--accent-hover);
    text-decoration: none;
}

