    padding: var(--spacing-xl) 0 0 0;
    margin-top: var(--spacing-xl);
    border-top: 1px solid #333;
}

.footer-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-xl);
    justify-content: space-between;
}

.footer-links {
