    flex-wrap: wrap;
    gap: var(--spacing-xl);
}

.footer-col h4 {
    margin-bottom: var(--spacing-md);
    font-size: 1.1rem;
}

.footer-col ul li {
    margin-bottom: var(--spacing-sm);
}

.footer-col a {
    color: var(--text-secondary);
    text-decoration: none;
}
.footer-col a:hover {
    color: var(--text-primary);
    text-decoration: underline;
}

.footer-bottom {
    text-align: center;
    padding: var(--spacing-md);
