const fs = require('fs');
const path = require('path');
const axeCore = require('axe-core');

(async () => {
    const browser = await puppeteer.launch();
    const page = await browser.newPage();

    // To test styling and layout, it's best to serve the files, but we can also use file:// URLs
    const htmlPath = path.resolve('src/index.html');
    await page.goto(`file://${htmlPath}`);

    // Inject axe-core
    await page.addScriptTag({ content: axeCore.source });

    // Run axe
    const results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    await browser.close();

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }, null, 2));

    if (wcag.length > 0) {
        process.exit(1);
    }
})();
