document.addEventListener('DOMContentLoaded', () => {
    // Add simple add to cart interaction
    const addToCartBtns = document.querySelectorAll('.product-info button');
    let cartCount = 0;
    const cartBtn = document.querySelector('.header-actions button');

    addToCartBtns.forEach(btn => {
        btn.addEventListener('click', (e) => {
            const btnEl = e.currentTarget;
            const originalText = btnEl.textContent;

            // Visual feedback
            btnEl.textContent = 'Added!';
            btnEl.style.backgroundColor = 'var(--accent-color)';
            btnEl.style.color = '#121212';

            // Update cart count
            cartCount++;
            cartBtn.setAttribute('aria-label', `Shopping Cart, ${cartCount} items`);

            // Optional: Live region announcement
            let liveRegion = document.getElementById('cart-announcer');
            if (!liveRegion) {
                liveRegion = document.createElement('div');
                liveRegion.id = 'cart-announcer';
                liveRegion.setAttribute('aria-live', 'polite');
                liveRegion.className = 'sr-only';
                liveRegion.style.position = 'absolute';
                liveRegion.style.width = '1px';
                liveRegion.style.height = '1px';
                liveRegion.style.padding = '0';
                liveRegion.style.margin = '-1px';
                liveRegion.style.overflow = 'hidden';
                liveRegion.style.clip = 'rect(0, 0, 0, 0)';
                liveRegion.style.whiteSpace = 'nowrap';
                liveRegion.style.border = '0';
                document.body.appendChild(liveRegion);
            }
            // Use the aria-label to tell them what was added
            const itemContext = btnEl.getAttribute('aria-label').split(': ')[1] || 'Item';
            liveRegion.textContent = `${itemContext} added to cart. Cart now has ${cartCount} items.`;

            setTimeout(() => {
                btnEl.textContent = originalText;
                btnEl.style.backgroundColor = '';
                btnEl.style.color = '';
            }, 2000);
        });
    });
});

const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');
const axeCore = require('axe-core');

(async () => {
    const browser = await puppeteer.launch();
    const page = await browser.newPage();

    // To test styling and layout, it's best to serve the files, but we can also use file:// URLs
    const htmlPath = path.resolve('src/index.html');
    await page.goto(`file://${htmlPath}`);

    // Inject axe-core
    await page.addScriptTag({ content: axeCore.source });

    // Run axe
    const results = await page.evaluate(async () => {
        return await window.axe.run();
    });

    await browser.close();

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }, null, 2));

    if (wcag.length > 0) {
        process.exit(1);
    }
})();

