    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 2rem;
    --spacing-xl: 4rem;
}

/* Reset & Base Styles */
* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: var(--font-family);
    line-height: 1.6;
}

a {
    color: var(--text-primary);
    text-decoration: underline;
    text-decoration-color: var(--text-secondary);
    text-underline-offset: 4px;
}

a:hover {
    text-decoration-color: var(--accent-color);
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

ul {
    list-style: none;
}

button {
    font-family: inherit;
    cursor: pointer;
    background: none;
    border: none;
    color: inherit;
}

/* Focus styles for accessibility */
:focus-visible {
    outline: 2px solid var(--focus-ring);
    outline-offset: 2px;
}

/* Skip link */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: #000;
    padding: 8px;
    z-index: 100;
    transition: top 0.2s;
    text-decoration: none;
    font-weight: bold;
}
.skip-link:focus {
    top: 0;
}

/* Header */
header {
    background-color: var(--surface-color);
    border-bottom: 1px solid #333;
    padding: 1rem 0;
    position: sticky;
    top: 0;
    z-index: 10;
}

.header-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-md);
}

.logo {
    font-size: 1.5rem;
    letter-spacing: 2px;
    text-decoration: none;
}
.logo:hover {
    text-decoration: none;
}

nav[aria-label="Primary"] ul {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
}
nav[aria-label="Primary"] a {
    text-decoration: none;
    font-weight: 500;
}
nav[aria-label="Primary"] a:hover {
    color: var(--accent-color);
    text-decoration: underline;
}

.header-actions button {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0.5rem;
    border-radius: 4px;
}
.header-actions button:hover {
    background-color: #333;
}

/* Main content */
#maincontent {
    /* remove outline from tabindex="-1" */
    outline: none;
}

section {
    padding: var(--spacing-xl) var(--spacing-md);
    max-width: 1200px;
    margin: 0 auto;
}

section h2 {
    font-size: 2rem;
    margin-bottom: var(--spacing-lg);
    border-bottom: 1px solid #333;
    padding-bottom: var(--spacing-sm);
}

/* Hero Section */
.hero {
    min-height: 60vh;
    display: flex;
    align-items: center;
    background: linear-gradient(rgba(18, 18, 18, 0.7), rgba(18, 18, 18, 0.7)), url('https://images.unsplash.com/photo-1617137968427-85924c800a22?auto=format&fit=crop&w=1200&q=80') center/cover no-repeat;
    padding: var(--spacing-xl) var(--spacing-md);
    text-align: center;
    max-width: 100%;
}

.hero-content {
    max-width: 800px;
    margin: 0 auto;
}

.hero h1 {
    font-size: 3rem;
    margin-bottom: var(--spacing-md);
    line-height: 1.2;
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    margin-bottom: var(--spacing-lg);
}

.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    font-weight: bold;
    text-decoration: none;
    border-radius: 4px;
    text-align: center;
}

.btn-primary {
    background-color: var(--accent-color);
    color: #121212;
}

.btn-primary:hover {
    background-color: var(--accent-hover);
    text-decoration: none;
}

/* Grids */
.grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: var(--spacing-lg);
}

/* Product Cards */
.product-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    border: 1px solid #333;
}

.product-card .img-container {
    aspect-ratio: 1 / 1;
    overflow: hidden;
    background-color: #111;
}

.product-card img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.product-info {
    padding: var(--spacing-md);
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-info h3 {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-sm);
}

.product-info h3 a {
    text-decoration: none;
}
.product-info h3 a:hover {
    text-decoration: underline;
}

.product-info .price {
    font-weight: bold;
    color: var(--text-secondary);
    margin-bottom: var(--spacing-md);
    font-size: 1.1rem;
}

.product-info button {
    margin-top: auto;
    width: 100%;
    padding: 0.75rem;
    background-color: #333;
    color: var(--text-primary);
    border: 1px solid #444;
    border-radius: 4px;
    font-weight: bold;
    transition: background-color 0.2s;
}

.product-info button:hover {
    background-color: #444;
}

/* Deals / Promo Cards */
.promo-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    padding: var(--spacing-lg);
    border: 1px solid #333;
    display: flex;
    flex-direction: column;
    justify-content: center;
    position: relative;
    overflow: hidden;
}

.promo-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    border-left: 4px solid var(--accent-color);
}

.promo-card.bg-accent {
    background-color: #2c2c2c;
}

.promo-card h3 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-sm);
}

.promo-card h3 a {
    text-decoration: none;
}
.promo-card h3 a::after {
    /* Make the whole card clickable */
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
}

.promo-card p {
    color: var(--text-secondary);
    margin-bottom: var(--spacing-md);
}

.promo-link {
    color: var(--accent-color);
    font-weight: bold;
}

/* Editorial Cards */
.editorial-grid {
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
}

.article-card {
    background-color: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid #333;
}

.article-card img {
    aspect-ratio: 16 / 9;
    object-fit: cover;
}

.article-content {
    padding: var(--spacing-md);
}

.article-content h3 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-sm);
}
.article-content h3 a {
    text-decoration: none;
}
.article-content p {
    color: var(--text-secondary);
    margin-bottom: var(--spacing-md);
}

.article-content .meta {
    font-size: 0.9rem;
    color: #888;
    margin-bottom: 0;
}

/* Footer */
footer {
    background-color: #0a0a0a;
    padding: var(--spacing-xl) 0 0 0;
    margin-top: var(--spacing-xl);
    border-top: 1px solid #333;
}

.footer-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-xl);
    justify-content: space-between;
}

.footer-links {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-xl);
}

.footer-col h4 {
    margin-bottom: var(--spacing-md);
    font-size: 1.1rem;
}

.footer-col ul li {
    margin-bottom: var(--spacing-sm);
}

.footer-col a {
    color: var(--text-secondary);
    text-decoration: none;
}
.footer-col a:hover {
    color: var(--text-primary);
    text-decoration: underline;
}

.footer-bottom {
    text-align: center;
    padding: var(--spacing-md);
    margin-top: var(--spacing-lg);
    border-top: 1px solid #333;
    color: #666;
    font-size: 0.9rem;
}

/* Responsive adjust */
@media (max-width: 768px) {
