const fs = require('fs');
const path = require('path');
const axe = require('axe-core');
const { JSDOM } = require('jsdom');

(async () => {
    const htmlPath = path.resolve('index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');

    const dom = new JSDOM(html, {
        url: "http://localhost/",
        runScripts: "dangerously" 
    });

    const { window } = dom;
    const { document } = window;

    window.eval(axe.source);

    const results = await window.axe.run(document);

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
        wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
        bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }, null, 2));

    if (wcag.length > 0) {
        process.exit(1);
    }
})();

